package dev.sigmarix.quests;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class QuestEditorActionsTest {
    private QuestCore.Book book(){QuestCore.Book book=new QuestCore.Book();for(String id:Arrays.asList("a","b","c")){QuestCore.Quest quest=new QuestCore.Quest();quest.id=id;quest.title=id;QuestCore.Task task=new QuestCore.Task();task.type="check";quest.tasks.add(task);book.quests.add(quest);}return book;}
    @Test public void multiDependencyEditRejectsWholeCyclicTransactionWithoutMutatingLiveBook(){QuestCore.Book book=book();book.quests.get(0).dependencies.add("c");Set<String> selection=new LinkedHashSet<String>(Arrays.asList("a","b"));try{QuestEditorActions.dependencies(book,selection,"c",true,true);fail();}catch(IllegalArgumentException expected){}assertTrue(book.quests.get(1).dependencies.isEmpty());assertTrue(book.quests.get(2).dependencies.isEmpty());QuestCore.Book updated=QuestEditorActions.dependencies(book,selection,"c",false,true);assertEquals(Collections.singletonList("c"),updated.quests.get(1).dependencies);assertTrue(book.quests.get(1).dependencies.isEmpty());}
    @Test public void selectionMovementIsChapterScopedAndKeepsFractionalSteps(){QuestCore.Book book=book();QuestCore.Chapter chapter=new QuestCore.Chapter();chapter.id="other";chapter.title="Other";book.chapters.add(chapter);book.quests.get(2).chapter="other";QuestCore.Book moved=QuestEditorActions.move(book,new LinkedHashSet<String>(Arrays.asList("a","b","c")),"",.1,-.5);assertEquals(.1,moved.quests.get(0).x,0);assertEquals(-.5,moved.quests.get(1).y,0);assertEquals(0,moved.quests.get(2).x,0);assertEquals(0,book.quests.get(0).x,0);}
}
